window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/06_tools_build_debug/03_debugging.md"] = [{"id":"content/06_tools_build_debug/03_debugging.md:789ba151595f5e43:1","question":"<p>(L1, T) Что такое debugging symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Debug symbols связывают machine addresses с source lines, functions, types и variables. Их наличие не отменяет effects оптимизации.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":31},{"id":"content/06_tools_build_debug/03_debugging.md:7bfe7a21babd500f:1","question":"<p>(L1, T) Что делает флаг <code>-g</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>-g</code> добавляет debug information, обычно DWARF на Linux. Optimization и assertions задаются другими flags.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":37},{"id":"content/06_tools_build_debug/03_debugging.md:3af0d1566cf36728:1","question":"<p>(L1, T) Чем debug build отличается от release build с точки зрения отладки?</p>\n","answer":"<p><strong>Ответ:</strong> Debug обычно упрощает source-level stepping; optimized release может inline/remove/reorder code. Release тоже следует собирать с сохраняемыми symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":43},{"id":"content/06_tools_build_debug/03_debugging.md:3029a21d0e1d716e:1","question":"<p>(L1, T) Что такое stack trace?</p>\n","answer":"<p><strong>Ответ:</strong> Stack trace — восстановленная последовательность активных function calls выбранного thread. Inlining, tail calls и corruption ограничивают её полноту.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":49},{"id":"content/06_tools_build_debug/03_debugging.md:e8581e7082299e5b:1","question":"<p>(L1, T) Что такое stack frame?</p>\n","answer":"<p><strong>Ответ:</strong> Frame содержит контекст вызова: return location, saved state и доступные locals/arguments. Реальный layout зависит от ABI и optimization.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":55},{"id":"content/06_tools_build_debug/03_debugging.md:a5718a078c288a68:1","question":"<p>(L1, T) Как вызовы функций формируют call stack?</p>\n","answer":"<p><strong>Ответ:</strong> Вызовы создают необходимые activation records, возврат восстанавливает caller state. Inlining и tail calls могут убрать отдельные physical frames.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":61},{"id":"content/06_tools_build_debug/03_debugging.md:4732dce7adfe3d43:1","question":"<p>(L1, T) Что такое core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Core dump — snapshot части process state при событии: memory mappings, registers и threads. Это чувствительный artifact, который может содержать secrets.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":67},{"id":"content/06_tools_build_debug/03_debugging.md:c57ce558f456d845:1","question":"<p>(L1, P) Как включить генерацию core dump через <code>ulimit</code>?</p>\n","answer":"<p><strong>Ответ:</strong> В shell: <code>ulimit -c unlimited</code>, затем запускают process из этого environment. Также проверяют core_pattern, service limits и collector policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":73},{"id":"content/06_tools_build_debug/03_debugging.md:0c40044c67cdd347:1","question":"<p>(L1, P) Как проверить, что core dump действительно создается?</p>\n","answer":"<p><strong>Ответ:</strong> В controlled test вызывают известный crash и проверяют configured core location/collector. Не создают аварии в production ради проверки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":79},{"id":"content/06_tools_build_debug/03_debugging.md:72058e415575236f:1","question":"<p>(L1, T) Почему без <code>-g</code> отладка сильно ограничена?</p>\n","answer":"<p><strong>Ответ:</strong> Без matching debug info доступны addresses/exported symbols и disassembly, но source/types/locals часто отсутствуют. Их нельзя восстановить только включением <code>-g</code> после crash.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L1","line":85},{"id":"content/06_tools_build_debug/03_debugging.md:191fa4a0e1e1e1a0:1","question":"<p>(L2, T) Какие данные попадают в debug symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Обычно сохраняются source mapping, function/type descriptions и variable location information. Optimized-out values могут не иметь восстанавливаемого location.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L2","line":93},{"id":"content/06_tools_build_debug/03_debugging.md:25ee51f24c89aa78:1","question":"<p>(L2, T) Почему оптимизации ухудшают качество stack trace?</p>\n","answer":"<p><strong>Ответ:</strong> Inlining и tail calls меняют видимые frames; code motion затрудняет source mapping. Это не обязательно ошибка unwinder.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L2","line":99},{"id":"content/06_tools_build_debug/03_debugging.md:7581ede92235c7d5:1","question":"<p>(L2, T) Как frame pointer связан с backtrace?</p>\n","answer":"<p><strong>Ответ:</strong> Frame-pointer chain может помочь проходить frames. Альтернатива — unwind metadata; отсутствие frame pointer не означает невозможность backtrace.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimization Options</a>.</p>\n","group":"L2","line":105},{"id":"content/06_tools_build_debug/03_debugging.md:d01679aa36dbc7fb:1","question":"<p>(L2, T) Что делает <code>-fno-omit-frame-pointer</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Флаг уменьшает omission frame pointers, облегчая ряд profilers/unwinders. Гарантии зависят от target и function kind.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimization Options</a>.</p>\n","group":"L2","line":111},{"id":"content/06_tools_build_debug/03_debugging.md:ed27f6fe2c16edc9:1","question":"<p>(L2, P) Как получить stack trace из упавшего процесса?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gdb ./app core</code> и <code>thread apply all bt full</code>; нужны matching executable/libraries/debug info. Для live процесса возможен attach.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L2","line":117},{"id":"content/06_tools_build_debug/03_debugging.md:48190067c2495410:1","question":"<p>(L2, P) Как посмотреть системные настройки core dump в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют <code>ulimit -c</code>, <code>/proc/sys/kernel/core_pattern</code> и service/collector limits. Также учитывают permissions, disk и dump filters.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":123},{"id":"content/06_tools_build_debug/03_debugging.md:a566af8bb2948637:1","question":"<p>(L2, D) Почему core dump не появился после падения программы?</p>\n","answer":"<p><strong>Ответ:</strong> Причины: лимит, collector destination, permissions, space, dumpability или signal без core action. Проверяют policy до предположения об ошибке application.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":129},{"id":"content/06_tools_build_debug/03_debugging.md:ed0356e5affb0cbe:1","question":"<p>(L2, D) Почему stack trace неполный или “сломанный”?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны missing/wrong unwind info, optimized frames, mismatched binaries или stack corruption. Проверяют artifacts и registers/disassembly, не доверяют случайным адресам.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L2","line":135},{"id":"content/06_tools_build_debug/03_debugging.md:46b8934edac763f5:1","question":"<p>(L2, T) Что такое signal и какие сигналы обычно приводят к crash?</p>\n","answer":"<p><strong>Ответ:</strong> Signals уведомляют process/thread о событиях; SIGSEGV, SIGABRT, SIGILL и SIGBUS часто связаны с crash. Default actions различаются.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>.</p>\n","group":"L2","line":141},{"id":"content/06_tools_build_debug/03_debugging.md:fff500686f083787:1","question":"<p>(L2, T) Чем <code>SIGSEGV</code> отличается от <code>SIGABRT</code>?</p>\n","answer":"<p><strong>Ответ:</strong> SIGSEGV обычно сообщает invalid memory access; SIGABRT часто вызван abort/assert/runtime check. Конкретную первопричину определяют по context.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>.</p>\n","group":"L2","line":147},{"id":"content/06_tools_build_debug/03_debugging.md:b02e6f16493ac504:1","question":"<p>(L3, T) Как DWARF связан с debug symbols?</p>\n","answer":"<p><strong>Ответ:</strong> DWARF — формат debug descriptions для source/types/locations и related unwind data. ELF служит контейнером соответствующих sections.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/contents.html\">System V ABI: ELF</a>.</p>\n","group":"L3","line":155},{"id":"content/06_tools_build_debug/03_debugging.md:9b70428de8b23575:1","question":"<p>(L3, T) Как устроено unwind stack trace на Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Unwinder использует registers, unwind rules/metadata и иногда frame pointers. Для shared objects нужны корректные mappings/load addresses.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L3","line":161},{"id":"content/06_tools_build_debug/03_debugging.md:499c8e95cda26b44:1","question":"<p>(L3, T) Почему tail-call optimization мешает отладке?</p>\n","answer":"<p><strong>Ответ:</strong> Tail-call может заменить caller frame переходом в callee. Поэтому logical call history не всегда представлена physical stack frames.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimization Options</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":167},{"id":"content/06_tools_build_debug/03_debugging.md:42c7099e43ea13b1:1","question":"<p>(L3, D) Почему адреса в stack trace есть, а имен функций нет?</p>\n","answer":"<p><strong>Ответ:</strong> Нет matching symbols/debug packages, binary stripped или неверны runtime mappings. Проверяют build-id и load bias перед symbolication.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L3","line":173},{"id":"content/06_tools_build_debug/03_debugging.md:a0da4c1ae1ef514f:1","question":"<p>(L3, P) Как использовать <code>addr2line</code> для расшифровки адресов?</p>\n","answer":"<p><strong>Ответ:</strong> <code>addr2line -e app -f -C 0xADDRESS</code>; для PIE/shared objects нужен address с учётом load bias, не raw ASLR PC.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/\">GNU Binutils</a>.</p>\n","group":"L3","line":179},{"id":"content/06_tools_build_debug/03_debugging.md:b82f04f7281f9ed2:1","question":"<p>(L3, D) Почему crash воспроизводится только в release-сборке?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнивают UB/races, defines, allocator/layout и exact flags. Сохраняют production-like optimized build с symbols, а не заменяют его сразу Debug.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimization Options</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L3","line":185},{"id":"content/06_tools_build_debug/03_debugging.md:fd2633ee92ef0b7e:1","question":"<p>(L3, D) Как дебажить optimized-out variables?</p>\n","answer":"<p><strong>Ответ:</strong> Исследуют registers/disassembly и доступные value locations; иногда значение уже невозможно восстановить. Для нового run меняют instrumentation или targeted optimization.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L3","line":191},{"id":"content/06_tools_build_debug/03_debugging.md:7c98b88aab89c6db:1","question":"<p>(L3, T) Что такое separate debug symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Debug information хранится отдельно от runtime binary с надёжной связью по build-id/debuglink. Это уменьшает deployed size без потери diagnosis.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L3","line":197},{"id":"content/06_tools_build_debug/03_debugging.md:e14ed7083c9da5e0:1","question":"<p>(L3, P) Как отделить символы от бинаря и использовать их отдельно?</p>\n","answer":"<p><strong>Ответ:</strong> Например: <code>objcopy --only-keep-debug app app.debug</code>, <code>strip --strip-debug app</code>, <code>objcopy --add-gnu-debuglink=app.debug app</code>. Архивируют исходный build.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/\">GNU Binutils</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":203},{"id":"content/06_tools_build_debug/03_debugging.md:e6209ee07f091f41:1","question":"<p>(L3, D) Как понять, соответствует ли core dump именно этому бинарю?</p>\n","answer":"<p><strong>Ответ:</strong> Сверяют build-id, architecture, mappings и release metadata всех relevant modules. Совпадение имени файла недостаточно.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/contents.html\">System V ABI: ELF</a>.</p>\n","group":"L3","line":209},{"id":"content/06_tools_build_debug/03_debugging.md:50f11eaa58715190:1","question":"<p>(L4, T) Как устроена инфраструктура symbol server / debug package в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Debug artifacts индексируют по build-id и выдают debugger по configured search/debuginfod. Доступ, retention и provenance должны быть управляемыми.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L4","line":217},{"id":"content/06_tools_build_debug/03_debugging.md:01995b5039c4f8c5:1","question":"<p>(L4, S) Как организовать хранение debug symbols для production?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют exact binaries/debug info/dependencies по release/build-id с retention и access policy. Crash должен автоматически ссылаться на этот inventory.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L4","line":223},{"id":"content/06_tools_build_debug/03_debugging.md:bff9cc055080b53c:1","question":"<p>(L4, D) Как расследовать crash при частично поврежденном stack?</p>\n","answer":"<p><strong>Ответ:</strong> Начинают с fault PC/registers и reliable frames, проверяют stack memory и mappings. Предполагаемые frames помечают как гипотезы, не точную историю.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L4","line":229},{"id":"content/06_tools_build_debug/03_debugging.md:a1cbc423f6ebae8a:1","question":"<p>(L4, S) Как проектировать build/debug pipeline, чтобы post-mortem был надежным?</p>\n","answer":"<p><strong>Ответ:</strong> Pipeline создаёт build-id, matching debug artifacts и immutable release metadata, проверяет unwind/symbolication smoke test и configured core collection.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html\">GCC: Options</a>.</p>\n","group":"L4","line":235},{"id":"content/06_tools_build_debug/03_debugging.md:29960e4db1bf3cb4:1","question":"<p>(L4, D) Как восстанавливать контекст падения при отсутствии полного core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Используют minidump/registers, addresses, maps, logs и version metadata. Недоступные memory/state явно ограничивают выводы.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L4","line":241},{"id":"content/06_tools_build_debug/03_debugging.md:8df1c65246404b01:1","question":"<p>(L1, T) Что такое GDB?</p>\n","answer":"<p><strong>Ответ:</strong> GDB — debugger, управляющий execution и исследующий live process или core, registers, memory и source context.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":253},{"id":"content/06_tools_build_debug/03_debugging.md:32d29cd1a2eea1bd:1","question":"<p>(L1, P) Как запустить программу под GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gdb --args ./app arg1</code>, затем <code>run</code>. Подбирают environment и working directory, соответствующие воспроизведению.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":259},{"id":"content/06_tools_build_debug/03_debugging.md:87a3dcf121c8edf5:1","question":"<p>(L1, P) Как поставить обычный breakpoint?</p>\n","answer":"<p><strong>Ответ:</strong> <code>break main</code> или <code>break file.cpp:42</code>. Breakpoint связывается с доступным code location; pending/shared-library cases учитывают отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":265},{"id":"content/06_tools_build_debug/03_debugging.md:fd6dc395e8e27893:1","question":"<p>(L1, P) В чем разница между <code>run</code> и <code>start</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>run</code> запускает до остановки/завершения; <code>start</code> ставит временную остановку у начала main и запускает process.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":271},{"id":"content/06_tools_build_debug/03_debugging.md:99e596302dbf095f:1","question":"<p>(L1, P) Что делают команды <code>step</code>, <code>next</code>, <code>finish</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>step</code> входит в вызовы, <code>next</code> проходит source line без обычного входа, <code>finish</code> выполняет до возврата текущего frame. Optimization меняет stepping.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":277},{"id":"content/06_tools_build_debug/03_debugging.md:50b8584fad11c9e8:1","question":"<p>(L1, P) Как посмотреть backtrace?</p>\n","answer":"<p><strong>Ответ:</strong> <code>bt</code> показывает текущий thread; <code>bt full</code> добавляет доступные locals, <code>thread apply all bt</code> — все threads.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":283},{"id":"content/06_tools_build_debug/03_debugging.md:baffc2c5f1e83c05:1","question":"<p>(L1, P) Как вывести значение переменной?</p>\n","answer":"<p><strong>Ответ:</strong> <code>print variable</code> или <code>p expression</code> в выбранном frame. Вычисление некоторых expressions может вызвать code, поэтому в diagnosis это учитывают.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":289},{"id":"content/06_tools_build_debug/03_debugging.md:9dc4e6c46feea258:1","question":"<p>(L1, P) Как продолжить выполнение после остановки?</p>\n","answer":"<p><strong>Ответ:</strong> Команда <code>continue</code> (<code>c</code>) продолжает до следующей остановки или exit. Для signal handling учитывают debugger policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":295},{"id":"content/06_tools_build_debug/03_debugging.md:6cbc0e5729be47d1:1","question":"<p>(L1, P) Как выйти из GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>quit</code> (<code>q</code>); debugger уточняет судьбу active inferior при необходимости. Для attached process предварительно используют <code>detach</code>, если нужно продолжить его работу.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":301},{"id":"content/06_tools_build_debug/03_debugging.md:544d2f665cb54952:1","question":"<p>(L1, T) В чем разница между source-level и instruction-level debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Source-level использует lines/types, instruction-level — registers и machine instructions. При optimized code второй режим часто необходим.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L1","line":307},{"id":"content/06_tools_build_debug/03_debugging.md:109146eff41d7dde:1","question":"<p>(L2, P) Как поставить conditional breakpoint?</p>\n","answer":"<p><strong>Ответ:</strong> <code>break file.cpp:42 if count &gt; 100</code> либо <code>condition N expression</code>. Условие должно быть valid в соответствующем frame context.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":315},{"id":"content/06_tools_build_debug/03_debugging.md:919d2d0c5e803256:1","question":"<p>(L2, P) Как поставить breakpoint по имени функции?</p>\n","answer":"<p><strong>Ответ:</strong> <code>break Namespace::function</code>; overloads/templates могут дать несколько locations. Проверяют <code>info breakpoints</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":321},{"id":"content/06_tools_build_debug/03_debugging.md:002cb03dc5fe31aa:1","question":"<p>(L2, P) Как поставить breakpoint по файлу и строке?</p>\n","answer":"<p><strong>Ответ:</strong> <code>break source.cpp:42</code>; при relocated source tree настраивают source path/substitution. Optimizer мог убрать отдельную строку.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":327},{"id":"content/06_tools_build_debug/03_debugging.md:c5186e30657b9a4f:1","question":"<p>(L2, P) Что такое watchpoint?</p>\n","answer":"<p><strong>Ответ:</strong> Watchpoint останавливает при изменении expression/memory location. <code>watch</code>, <code>rwatch</code>, <code>awatch</code> имеют разные semantics и hardware constraints.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":333},{"id":"content/06_tools_build_debug/03_debugging.md:3f299dd2c81273bb:1","question":"<p>(L2, P) Как смотреть память по адресу?</p>\n","answer":"<p><strong>Ответ:</strong> Например, <code>x/16xb address</code> показывает 16 bytes, <code>x/8gx address</code> — восемь 8-byte units. Проверяют valid mapping и target architecture.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":339},{"id":"content/06_tools_build_debug/03_debugging.md:0710934ce774330c:1","question":"<p>(L2, P) Как напечатать register'ы?</p>\n","answer":"<p><strong>Ответ:</strong> <code>info registers</code>, для расширенного набора — <code>info all-registers</code>. Значения интерпретируют по ABI и текущей instruction.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":345},{"id":"content/06_tools_build_debug/03_debugging.md:d6f18e1769fa4982:1","question":"<p>(L2, P) Как attach'иться к уже запущенному процессу?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gdb -p PID</code>; нужны ptrace permissions и подходящий namespace/security context. Attach обычно временно останавливает threads.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":351},{"id":"content/06_tools_build_debug/03_debugging.md:13d93209ee2dd34a:1","question":"<p>(L2, D) Когда attach полезнее, чем запуск под GDB?</p>\n","answer":"<p><strong>Ответ:</strong> Attach сохраняет уже возникшее состояние long-running process, например hang. Он меняет scheduling и может повлиять на timing-sensitive bug.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":357},{"id":"content/06_tools_build_debug/03_debugging.md:c493cf54ad8f2677:1","question":"<p>(L2, P) Как переключаться между потоками в GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>info threads</code>, затем <code>thread N</code>, где N — GDB thread ID. Это не обязательно Linux TID.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":363},{"id":"content/06_tools_build_debug/03_debugging.md:c84a1046389e899f:1","question":"<p>(L2, D) Как найти поток, который завис или держит mutex?</p>\n","answer":"<p><strong>Ответ:</strong> <code>thread apply all bt</code> выявляет waits и active owners; mutex ownership зависит от реализации. Строят wait-for relationships и подтверждают state.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L2","line":369},{"id":"content/06_tools_build_debug/03_debugging.md:2b341850b6f3d056:1","question":"<p>(L3, T) В чем разница hardware watchpoint vs software watchpoint?</p>\n","answer":"<p><strong>Ответ:</strong> Hardware watchpoint использует CPU debug facilities с ограничениями count/size. Software watchpoint требует дорогого stepping/comparison и имеет другие restrictions.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":377},{"id":"content/06_tools_build_debug/03_debugging.md:5ed6ce7dd8347ae4:1","question":"<p>(L3, D) Почему breakpoint “не срабатывает”?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют execution path, actual binary, symbols, inline/removed code, pending library и breakpoint conditions. Номер строки не гарантирует executable location.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":383},{"id":"content/06_tools_build_debug/03_debugging.md:bcbc246b80deb1c1:1","question":"<p>(L3, D) Почему GDB показывает <code>&lt;optimized out&gt;</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизатор удалил variable или её location/value недоступны в этой точке. Debug info не обязан хранить все исходные values.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":389},{"id":"content/06_tools_build_debug/03_debugging.md:c021679572183719:1","question":"<p>(L3, P) Как дебажить core dump через GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gdb ./app core</code>, затем <code>bt full</code>, <code>info registers</code>, <code>thread apply all bt</code>. Execution core продолжать нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":395},{"id":"content/06_tools_build_debug/03_debugging.md:e216f5334775c218:1","question":"<p>(L3, P) Как загрузить отдельные debug symbols в GDB?</p>\n","answer":"<p><strong>Ответ:</strong> Настраивают <code>set debug-file-directory</code>, matching debuglink/build-id или debuginfod. Symbols произвольной новой сборки применять нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":401},{"id":"content/06_tools_build_debug/03_debugging.md:1e3940bba5f78210:1","question":"<p>(L3, P) Как дизассемблировать текущую функцию?</p>\n","answer":"<p><strong>Ответ:</strong> <code>disassemble /m function</code> или <code>x/10i $pc</code>; source mix зависит от debug info. Для crash важна фактическая machine instruction.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":407},{"id":"content/06_tools_build_debug/03_debugging.md:e8cd86ecb4dae9e2:1","question":"<p>(L3, P) Как смотреть аргументы функции и локальные переменные на каждом frame?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирают <code>frame N</code>, используют <code>info args</code> и <code>info locals</code>. Optimized values могут отсутствовать или иметь неполное location coverage.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":413},{"id":"content/06_tools_build_debug/03_debugging.md:611c41bad9096982:1","question":"<p>(L3, D) Как искать corruption памяти через watchpoint?</p>\n","answer":"<p><strong>Ответ:</strong> Ставят watch на known-valid location до её порчи и исследуют writer. Watchpoint после crash не восстановит уже прошедшее изменение.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":419},{"id":"content/06_tools_build_debug/03_debugging.md:294d5915c809a57e:1","question":"<p>(L3, D) Как дебажить multithreaded deadlock в GDB?</p>\n","answer":"<p><strong>Ответ:</strong> Собирают все stacks, определяют locks/resources и строят cycle ожиданий. Один blocked thread не доказывает deadlock; нужны владельцы и dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":425},{"id":"content/06_tools_build_debug/03_debugging.md:0daf4b452da1de53:1","question":"<p>(L3, P) Как использовать <code>thread apply all bt</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Команда выполняет backtrace для каждого thread: <code>thread apply all bt full</code>. Большой output может содержать sensitive values.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":431},{"id":"content/06_tools_build_debug/03_debugging.md:5aaa5dcd147ed43c:1","question":"<p>(L4, T) Как GDB работает с DWARF и unwind info?</p>\n","answer":"<p><strong>Ответ:</strong> GDB читает debug types/locations и unwind rules, связывая PC с source/frame. Совпадение artifacts и runtime mappings критично.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L4","line":439},{"id":"content/06_tools_build_debug/03_debugging.md:d16cd7042b15aa7e:1","question":"<p>(L4, D) Как дебажить race condition, которая редко воспроизводится?</p>\n","answer":"<p><strong>Ответ:</strong> Предпочитают TSan/stress/replay и narrow tracing: debugger меняет timing. GDB полезен для state, но не доказывает absence race.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L4","line":445},{"id":"content/06_tools_build_debug/03_debugging.md:872c6b2b1f82fe75:1","question":"<p>(L4, S) Как встроить GDB-based post-mortem анализ в production pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Автоматизируют безопасный batch разбор core с matched artifacts, сохраняют signature и ограничивают доступ/объём вывода. Сбор не должен блокировать recovery.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":451},{"id":"content/06_tools_build_debug/03_debugging.md:302426dc2cd6fe1a:1","question":"<p>(L4, D) Как расследовать crash внутри libc / libstdc++ / чужой <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала проверяют matching library symbols и caller arguments/lifetimes. Crash в allocator/libc часто является следствием более ранней corruption.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":457},{"id":"content/06_tools_build_debug/03_debugging.md:82940d0b301f72c2:1","question":"<p>(L4, D) Как использовать Python scripting в GDB для автоматизации расследований?</p>\n","answer":"<p><strong>Ответ:</strong> GDB Python API позволяет обходить threads/frames, читать values и создавать commands/pretty printers. Скрипты должны учитывать invalid memory и untrusted artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L4","line":463},{"id":"content/06_tools_build_debug/03_debugging.md:c4f8b180051d19ec:1","question":"<p>(L1, T) Что такое Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> Valgrind — framework dynamic instrumentation; Memcheck — один из его tools для memory errors. Названия не следует использовать как полные синонимы.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":477},{"id":"content/06_tools_build_debug/03_debugging.md:9b5c38d655425890:1","question":"<p>(L1, T) Что делает Memcheck?</p>\n","answer":"<p><strong>Ответ:</strong> Memcheck отслеживает addressability/definedness и сообщает invalid accesses, misuse allocation и leaks. Он не обнаруживает все логические или concurrency errors.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":483},{"id":"content/06_tools_build_debug/03_debugging.md:bb9c18b56d0d98fa:1","question":"<p>(L1, T) Что такое memory leak?</p>\n","answer":"<p><strong>Ответ:</strong> Leak — allocated memory, которой больше нельзя корректно распорядиться/освободить по ownership contract. Рост RSS сам по себе leak не доказывает.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":489},{"id":"content/06_tools_build_debug/03_debugging.md:526ddc1bb69056d5:1","question":"<p>(L1, T) Что такое use-after-free?</p>\n","answer":"<p><strong>Ответ:</strong> Это доступ после окончания lifetime/free allocation. Память может ещё содержать прежние bytes, но доступ уже некорректен.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":495},{"id":"content/06_tools_build_debug/03_debugging.md:d281752e20e7680e:1","question":"<p>(L1, T) Что такое invalid read / invalid write?</p>\n","answer":"<p><strong>Ответ:</strong> Чтение/запись address, недопустимого для операции, например вне allocation или после free. Memcheck сообщает size и relevant allocation context.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":501},{"id":"content/06_tools_build_debug/03_debugging.md:fa9b7e37249ead6c:1","question":"<p>(L1, P) Как запустить программу под Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> <code>valgrind --tool=memcheck ./app args</code>. Для source locations собирают с debug info и сохраняют controlled workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":507},{"id":"content/06_tools_build_debug/03_debugging.md:f19c38bab0db7319:1","question":"<p>(L1, P) Как включить leak detection?</p>\n","answer":"<p><strong>Ответ:</strong> <code>valgrind --leak-check=full --show-leak-kinds=all ./app</code>. Выходной статус для CI настраивают отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":513},{"id":"content/06_tools_build_debug/03_debugging.md:ce1a0f2ed9bf634f:1","question":"<p>(L1, D) Как интерпретировать “definitely lost”?</p>\n","answer":"<p><strong>Ответ:</strong> Memcheck не нашёл pointer к allocation: память считается definitely lost в текущем snapshot. Исследуют allocation stack и потерю ownership.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":519},{"id":"content/06_tools_build_debug/03_debugging.md:cdde320a161a25d8:1","question":"<p>(L1, D) Как интерпретировать “indirectly lost”?</p>\n","answer":"<p><strong>Ответ:</strong> Allocation достижима только через другую lost allocation, например nodes дерева после потери root. Исправление root ownership может устранить множество indirect leaks.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":525},{"id":"content/06_tools_build_debug/03_debugging.md:6e694fbb642e17f2:1","question":"<p>(L1, D) Чем leak отличается от still reachable?</p>\n","answer":"<p><strong>Ответ:</strong> Still reachable имеет найденный pointer path и может быть intentional pool/cache. Это не автоматическая ошибка, но policy требует объяснения lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":531},{"id":"content/06_tools_build_debug/03_debugging.md:5e6cf86f1f548068:1","question":"<p>(L2, D) Как по отчету Valgrind найти место утечки?</p>\n","answer":"<p><strong>Ответ:</strong> Report показывает allocation stack, а не обязательно строку потери pointer. Прослеживают ownership transitions и missing cleanup по соответствующему workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":539},{"id":"content/06_tools_build_debug/03_debugging.md:ee3d1fd2331807d4:1","question":"<p>(L2, P) Как использовать suppression files?</p>\n","answer":"<p><strong>Ответ:</strong> Файл подключают <code>--suppressions=path</code>; patterns делают узкими и документированными. Suppression скрывает diagnosis, а не исправляет memory defect.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":545},{"id":"content/06_tools_build_debug/03_debugging.md:bce80a39f065053f:1","question":"<p>(L2, T) Почему Valgrind сильно замедляет программу?</p>\n","answer":"<p><strong>Ответ:</strong> Он переводит и инструментирует machine code, ведёт shadow state и проверяет accesses. Поэтому CPU/memory overhead существенно выше обычного execution.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":551},{"id":"content/06_tools_build_debug/03_debugging.md:d718ce0ab8c1dbee:1","question":"<p>(L2, D) Какие классы ошибок хорошо ловит Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> Хорошо выявляет invalid heap accesses, use-after-free, double free, uninitialized-value use и leaks в наблюдённых paths.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":557},{"id":"content/06_tools_build_debug/03_debugging.md:5a6d05fe030e9249:1","question":"<p>(L2, D) Какие ошибки Valgrind ловит плохо или не ловит?</p>\n","answer":"<p><strong>Ответ:</strong> Не гарантирует обнаружение всех stack/global overflows, data races и logical lifetime errors внутри valid allocations. Невыполненный path не проверяется.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":563},{"id":"content/06_tools_build_debug/03_debugging.md:3fb2bcb233ecc692:1","question":"<p>(L2, T) Почему Valgrind хуже подходит для heavily optimized кода?</p>\n","answer":"<p><strong>Ответ:</strong> Optimization усложняет source mapping и меняет code patterns; instrumentation всё равно работает, но diagnosis становится менее прямой. Используют suitable debug build.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":569},{"id":"content/06_tools_build_debug/03_debugging.md:bcf10994de165c51:1","question":"<p>(L2, D) Что означает “conditional jump depends on uninitialised value”?</p>\n","answer":"<p><strong>Ответ:</strong> Управление потоком зависит от undefined bytes. Причина может быть раньше места branch; включают origin tracking и ищут initialization.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":575},{"id":"content/06_tools_build_debug/03_debugging.md:9fd63046da9f9dde:1","question":"<p>(L2, P) Как анализировать uninitialized memory через Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> <code>--track-origins=yes</code> добавляет сведения о происхождении uninitialized value. Это увеличивает overhead, зато сокращает путь к allocation/stack origin.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":581},{"id":"content/06_tools_build_debug/03_debugging.md:c8a3ea00885ac208:1","question":"<p>(L2, D) Как найти double free через Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> Report invalid free связывают с предыдущим free и allocation. Исправляют double ownership/cleanup race, а не только условие вокруг free.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":587},{"id":"content/06_tools_build_debug/03_debugging.md:b55758a49b9df2fa:1","question":"<p>(L2, D) Как найти heap corruption через Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала рассматривают первый invalid write/read по времени: поздний allocator crash часто вторичен. Уменьшают testcase и отслеживают ownership.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":593},{"id":"content/06_tools_build_debug/03_debugging.md:82390651d47d0ae3:1","question":"<p>(L3, T) Как Valgrind инструментирует код?</p>\n","answer":"<p><strong>Ответ:</strong> Valgrind переводит blocks machine code в внутреннее representation, добавляет tool instrumentation и исполняет преобразованные blocks.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":601},{"id":"content/06_tools_build_debug/03_debugging.md:4e517d40dd448f12:1","question":"<p>(L3, D) Почему под Valgrind баг исчезает?</p>\n","answer":"<p><strong>Ответ:</strong> Instrumentation меняет scheduling, memory layout и скорость. Исчезновение race/UB symptom не означает исправление.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L3","line":607},{"id":"content/06_tools_build_debug/03_debugging.md:f66244a52e9a7826:1","question":"<p>(L3, D) Почему Valgrind показывает много шума от сторонних библиотек?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны реальные bugs, unsupported patterns, missing symbols или известные tool/library interactions. Проверяют versions и минимальный пример до narrow suppression.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":613},{"id":"content/06_tools_build_debug/03_debugging.md:431e41480a1172a2:1","question":"<p>(L3, P) Как сочетать Valgrind и debug symbols для качественного анализа?</p>\n","answer":"<p><strong>Ответ:</strong> Собирают с <code>-g</code>, используют matching libraries и удобный уровень optimization. Тогда error stacks связываются с source locations.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":619},{"id":"content/06_tools_build_debug/03_debugging.md:2390a5aa45349a6f:1","question":"<p>(L3, D) Как анализировать leaks в long-running daemon?</p>\n","answer":"<p><strong>Ответ:</strong> Выделяют representative cycle, сравнивают leak/heap snapshots и allocation growth. Для полного daemon workload стоимость Memcheck может быть слишком высокой.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":625},{"id":"content/06_tools_build_debug/03_debugging.md:13207bf56eac97af:1","question":"<p>(L3, D) Как отличить реальную утечку от кешей/allocator pools?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнивают live allocations, удерживающие owners и plateau после нагрузки. Pools могут удерживать память законно, но unbounded growth всё равно требует limits.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":631},{"id":"content/06_tools_build_debug/03_debugging.md:79aad8a24b05c533:1","question":"<p>(L3, S) Когда Valgrind лучше ASan, а когда хуже?</p>\n","answer":"<p><strong>Ответ:</strong> Memcheck полезен без rebuild и для definedness; ASan обычно быстрее и лучше подходит частым instrumented tests. Coverage/platform restrictions сравнивают отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":637},{"id":"content/06_tools_build_debug/03_debugging.md:c46b68335a1f0c51:1","question":"<p>(L3, D) Как дебажить corruption, если stack trace указывает на allocator, а не на место ошибки?</p>\n","answer":"<p><strong>Ответ:</strong> Ищут ранний invalid access, allocation/free history и повреждённый object. Crash inside allocator указывает на обнаружение inconsistency, не обязательно её источник.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":643},{"id":"content/06_tools_build_debug/03_debugging.md:e969b74d7d297ab6:1","question":"<p>(L3, P) Как использовать Massif и когда это полезно?</p>\n","answer":"<p><strong>Ответ:</strong> <code>valgrind --tool=massif ./app</code> строит heap-usage profile во времени; анализируют allocation call trees. Это profiling объёма, не замена Memcheck.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>.</p>\n","group":"L3","line":649},{"id":"content/06_tools_build_debug/03_debugging.md:ecbe0e211d2f6bbc:1","question":"<p>(L3, T) Что такое origin tracking в Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> Origin tracking хранит происхождение undefined values и показывает, где они возникли. Он не выдаёт полную историю каждого присваивания.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":655},{"id":"content/06_tools_build_debug/03_debugging.md:88eb1ca2fdbca554:1","question":"<p>(L4, S) Как встроить Valgrind checks в CI без чрезмерного slowdown?</p>\n","answer":"<p><strong>Ответ:</strong> Запускают selected memory-focused tests отдельно/ночью, используют error-exitcode и controlled suppressions. Не подменяют полный coverage маленьким smoke test.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L4","line":663},{"id":"content/06_tools_build_debug/03_debugging.md:1d888d300baffc6d:1","question":"<p>(L4, D) Как расследовать memory corruption, который воспроизводится только на production-нагрузке?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют production artifacts/core, снимают low-overhead context и воспроизводят load в lab с sanitizers. Ищут early corruption, учитывая timing changes.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":669},{"id":"content/06_tools_build_debug/03_debugging.md:b5a40db8a60bd660:1","question":"<p>(L4, S) Как выбрать memory-debugging strategy для большого C/C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Комбинируют ASan/UBSan, TSan отдельно, Memcheck для definedness и heap profiles для роста. Coverage/overhead определяют этап запуска.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L4","line":675},{"id":"content/06_tools_build_debug/03_debugging.md:f44364dd867bea90:1","question":"<p>(L4, D) Как приоритизировать сотни Valgrind-репортов в legacy-коде?</p>\n","answer":"<p><strong>Ответ:</strong> Группируют по root stack/type, приоритизируют invalid writes/UAF и externally reachable paths. Сначала устраняют ранние общие causes, затем secondary reports.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L4","line":681},{"id":"content/06_tools_build_debug/03_debugging.md:75d02282a5c1fdf9:1","question":"<p>(L4, S) Как комбинировать Valgrind, ASan и post-mortem анализ?</p>\n","answer":"<p><strong>Ответ:</strong> Sanitizers дают быстрые instrumented runs, Memcheck дополняет definedness, core сохраняет state невоспроизведённого crash. Artifacts и workload связывают одной version metadata.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":687},{"id":"content/06_tools_build_debug/03_debugging.md:9f9e27a0a3d05929:1","question":"<p>(L1, T) Что такое AddressSanitizer?</p>\n","answer":"<p><strong>Ответ:</strong> ASan — compiler/runtime instrumentation для обнаружения многих address/lifetime errors в выполненном коде. Это не формальное доказательство memory safety.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":697},{"id":"content/06_tools_build_debug/03_debugging.md:48177665d1ef496d:1","question":"<p>(L1, T) Что такое UndefinedBehaviorSanitizer?</p>\n","answer":"<p><strong>Ответ:</strong> UBSan проверяет выбранные классы undefined behavior, например alignment и signed overflow. Он не охватывает всё UB языка.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>.</p>\n","group":"L1","line":703},{"id":"content/06_tools_build_debug/03_debugging.md:111f871e12f8f308:1","question":"<p>(L1, P) Как собрать программу с ASan?</p>\n","answer":"<p><strong>Ответ:</strong> Например: <code>clang++ -g -O1 -fsanitize=address -fno-omit-frame-pointer main.cpp -o app</code>. Sanitizer flag нужен и на final link.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":709},{"id":"content/06_tools_build_debug/03_debugging.md:0a2fb5646f683bd2:1","question":"<p>(L1, P) Как собрать программу с UBSan?</p>\n","answer":"<p><strong>Ответ:</strong> <code>clang++ -g -O1 -fsanitize=undefined main.cpp -o app</code>; recovery/trap policy задают отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>.</p>\n","group":"L1","line":715},{"id":"content/06_tools_build_debug/03_debugging.md:9bd7322ede695524:1","question":"<p>(L1, T) Какие ошибки ловит ASan?</p>\n","answer":"<p><strong>Ответ:</strong> Многие out-of-bounds, use-after-free, double/invalid free и selected stack lifetime errors. Возможности зависят от configuration/platform.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":721},{"id":"content/06_tools_build_debug/03_debugging.md:e278d0de250f3e05:1","question":"<p>(L1, T) Какие ошибки ловит UBSan?</p>\n","answer":"<p><strong>Ответ:</strong> Проверки включают signed overflow, invalid shifts, alignment и некоторые type/bounds cases. Набор флагов и ограничения сверяют с compiler docs.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>.</p>\n","group":"L1","line":727},{"id":"content/06_tools_build_debug/03_debugging.md:6d10c080d5e8a69f:1","question":"<p>(L1, D) Чем ASan отличается от Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> ASan инструментирует при compilation и использует runtime/shadow memory; Memcheck dynamically instrumentирует machine code. Overhead и detected classes различаются.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L1","line":733},{"id":"content/06_tools_build_debug/03_debugging.md:16325cfeadbf99ed:1","question":"<p>(L1, D) Что такое heap-buffer-overflow?</p>\n","answer":"<p><strong>Ответ:</strong> Это access за пределами heap allocation. Report связывают с размером allocation и offending instruction, а не только crash PC.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":739},{"id":"content/06_tools_build_debug/03_debugging.md:adb9f89d00122f7c:1","question":"<p>(L1, D) Что такое stack-buffer-overflow?</p>\n","answer":"<p><strong>Ответ:</strong> Это access вне допустимой области stack object. Не любой неверный index внутри одного большого allocation будет обнаружен.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":745},{"id":"content/06_tools_build_debug/03_debugging.md:ca8132e1eeddd7af:1","question":"<p>(L1, D) Что такое use-after-free?</p>\n","answer":"<p><strong>Ответ:</strong> Объект уже освобождён, но pointer/reference ещё используется. ASan может показать allocation и free stacks, помогая восстановить lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L1","line":751},{"id":"content/06_tools_build_debug/03_debugging.md:4013b620d97fc3fc:1","question":"<p>(L2, T) Как ASan инструментирует код?</p>\n","answer":"<p><strong>Ответ:</strong> Compiler добавляет проверки accesses, runtime поддерживает shadow memory и interceptors. Неинструментированный код снижает coverage.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":759},{"id":"content/06_tools_build_debug/03_debugging.md:9b34ae1bfa1acd2b:1","question":"<p>(L2, T) Что такое red zones?</p>\n","answer":"<p><strong>Ответ:</strong> Poisoned области вокруг objects позволяют обнаружить пересечение границы до порчи соседнего объекта. Redzones увеличивают memory footprint.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":765},{"id":"content/06_tools_build_debug/03_debugging.md:5eaf18b61d5b1e7e:1","question":"<p>(L2, D) Почему ASan может падать раньше, чем исходная программа без него?</p>\n","answer":"<p><strong>Ответ:</strong> ASan останавливается на обнаруженном invalid access раньше вторичного crash. Изменённый layout также может изменить момент проявления bug.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":771},{"id":"content/06_tools_build_debug/03_debugging.md:b26169b8c0c4d167:1","question":"<p>(L2, P) Как читать ASan stack trace?</p>\n","answer":"<p><strong>Ответ:</strong> Читают error type, access size/address, fault stack и allocation/free stacks. Исправляют ownership/bounds первопричину, не строку runtime reporter.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":777},{"id":"content/06_tools_build_debug/03_debugging.md:d29de541fb85d104:1","question":"<p>(L2, D) Как найти источник UB по отчету UBSan?</p>\n","answer":"<p><strong>Ответ:</strong> Берут точную source location, operands/type и violated rule из diagnostic. Проверяют исходную arithmetic/type logic и добавляют regression input.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>.</p>\n","group":"L2","line":783},{"id":"content/06_tools_build_debug/03_debugging.md:34fd8ba106380d54:1","question":"<p>(L2, T) Какие типы UB особенно важны в C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Особенно важны bounds/lifetime, signed arithmetic, alignment, invalid shifts и races. Для races используют отдельный TSan, не UBSan.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L2","line":789},{"id":"content/06_tools_build_debug/03_debugging.md:0208a849110aa560:1","question":"<p>(L2, D) Почему signed integer overflow считается UB?</p>\n","answer":"<p><strong>Ответ:</strong> Языковые правила не задают wraparound signed arithmetic. Для нужной modular arithmetic используют unsigned или checked операции согласно contract.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>.</p>\n","group":"L2","line":795},{"id":"content/06_tools_build_debug/03_debugging.md:caf93f75bf9f653b:1","question":"<p>(L2, P) Можно ли запускать ASan в тестах/CI?</p>\n","answer":"<p><strong>Ответ:</strong> Да: собирают и линкуют tests с sanitizer, запускают representative workload и сохраняют reports. Resource limits должны учитывать overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":801},{"id":"content/06_tools_build_debug/03_debugging.md:6d7364da82bce0b6:1","question":"<p>(L2, D) Почему sanitizer-сборка иногда требует отключить часть оптимизаций?</p>\n","answer":"<p><strong>Ответ:</strong> Умеренная optimization улучшает diagnosis, но ASan поддерживает optimized builds. Массовое отключение optimization может скрыть production-like paths.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":807},{"id":"content/06_tools_build_debug/03_debugging.md:c308b6b8cbc7d3ef:1","question":"<p>(L2, D) Что делать, если sanitizer нашел баг в third-party code?</p>\n","answer":"<p><strong>Ответ:</strong> Минимизируют report, проверяют supported version, обновляют/patch dependency и передают воспроизведение upstream. Suppression оправдана лишь после понятного analysis.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L2","line":813},{"id":"content/06_tools_build_debug/03_debugging.md:76ba09e69ff79c16:1","question":"<p>(L3, T) Ограничения ASan по сравнению с Valgrind?</p>\n","answer":"<p><strong>Ответ:</strong> ASan обычно требует rebuild и не отслеживает uninitialized-value use как Memcheck. Неинструментированные modules и intra-object accesses ограничивают coverage.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":821},{"id":"content/06_tools_build_debug/03_debugging.md:4f69ac1369337b84:1","question":"<p>(L3, T) Что такое ODR violation detection у sanitizer'ов?</p>\n","answer":"<p><strong>Ответ:</strong> ASan может выявлять selected ODR violations, например конфликтующие global definitions. Это не полный анализ ODR во всём C++ program.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":827},{"id":"content/06_tools_build_debug/03_debugging.md:a0855e9a2f253dbc:1","question":"<p>(L3, D) Почему sanitizer-сборка не воспроизводит production crash?</p>\n","answer":"<p><strong>Ответ:</strong> Layout, timing, allocation behavior, workload или instrumented coverage отличаются. Сохраняют production-like flags и исследуют races отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L3","line":833},{"id":"content/06_tools_build_debug/03_debugging.md:56c95a34bad0a6d8:1","question":"<p>(L3, D) Как расследовать intermittent use-after-free с ASan?</p>\n","answer":"<p><strong>Ответ:</strong> Запускают повторяемый stress/replay, сохраняют первый report с allocation/free stacks. Уточняют async ownership и cancellation races.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":839},{"id":"content/06_tools_build_debug/03_debugging.md:b42fff6bcf85e1b3:1","question":"<p>(L3, D) Как интерпретировать shadow memory report?</p>\n","answer":"<p><strong>Ответ:</strong> Shadow bytes описывают доступность application memory; legend связывает markers с freed/redzone states. Они помогают классификации, но не заменяют source stacks.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":845},{"id":"content/06_tools_build_debug/03_debugging.md:652bd9561a7fb8ff:1","question":"<p>(L3, T) Что такое leak sanitizer и как он связан с ASan?</p>\n","answer":"<p><strong>Ответ:</strong> LSan ищет unreachable heap allocations; на supported platforms он интегрирован с ASan либо запускается отдельно. Leak detection обычно выполняется на configured checkpoints/exit.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/LeakSanitizer.html\">Clang: LeakSanitizer</a>.</p>\n","group":"L3","line":851},{"id":"content/06_tools_build_debug/03_debugging.md:a85a7079fecabada:1","question":"<p>(L3, P) Как комбинировать ASan и UBSan в одной сборке?</p>\n","answer":"<p><strong>Ответ:</strong> Например, <code>-fsanitize=address,undefined</code> на compilation/link. ASan и TSan совместно в одном обычном build не комбинируют.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L3","line":857},{"id":"content/06_tools_build_debug/03_debugging.md:c81f1543d3d891f4:1","question":"<p>(L3, D) Почему sanitizer увеличивает memory footprint?</p>\n","answer":"<p><strong>Ответ:</strong> Shadow mapping, redzones, quarantine и allocation metadata увеличивают virtual/resident memory. Virtual address usage нельзя напрямую приравнивать RSS.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":863},{"id":"content/06_tools_build_debug/03_debugging.md:3ea0806aa0b94cc8:1","question":"<p>(L3, D) Как анализировать false positive / false negative sanitizer'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют instrumented coverage, custom allocators, supported platform и минимальный testcase. Реальный дефект не следует объявлять false positive из-за необычного stack.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":869},{"id":"content/06_tools_build_debug/03_debugging.md:75b181e7ca71906e:1","question":"<p>(L3, S) Как внедрить sanitizer pipeline в команду?</p>\n","answer":"<p><strong>Ответ:</strong> Начинают с stable selected tests, назначают owners/fix policy, затем расширяют coverage. Reports сохраняют с exact artifacts; новые failures должны быть actionable.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L3","line":875},{"id":"content/06_tools_build_debug/03_debugging.md:c3cc7e2fa44634c6:1","question":"<p>(L4, S) Как выбрать набор sanitizer'ов для разных стадий CI/CD?</p>\n","answer":"<p><strong>Ответ:</strong> PR: быстрые ASan/UBSan; отдельно TSan/concurrency tests; nightly — длинный stress/fuzz и дополнительные tools. Набор зависит от риска и platform support.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html\">Clang: UndefinedBehaviorSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L4","line":883},{"id":"content/06_tools_build_debug/03_debugging.md:684aa0ea17b924fb:1","question":"<p>(L4, D) Как расследовать баг, который проявляется только без sanitizer'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнивают workload/config и применяют release symbols, cores, narrow tracing и minimized testcase. Sanitizer success не исключает race/UB.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":889},{"id":"content/06_tools_build_debug/03_debugging.md:15b434730894d029:1","question":"<p>(L4, S) Как минимизировать стоимость sanitizer builds в большом монорепо?</p>\n","answer":"<p><strong>Ответ:</strong> Кешируют compatible builds, запускают impacted targets и шардируют tests. Nightly coverage дополняет PR subset; sanitizer configs не смешивают в одном artifact cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":895},{"id":"content/06_tools_build_debug/03_debugging.md:05e8484914b259a1:1","question":"<p>(L4, D) Как использовать sanitizer-репорты для поиска архитектурных проблем?</p>\n","answer":"<p><strong>Ответ:</strong> Повторяющиеся UAF показывают неясный ownership, bounds bugs — слабый parsing boundary. Группируют patterns и исправляют API/invariants, а не только отдельные crashes.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":901},{"id":"content/06_tools_build_debug/03_debugging.md:197acbb965f0ef50:1","question":"<p>(L4, S) Как построить policy: какие sanitizer'ы обязательны для merge?</p>\n","answer":"<p><strong>Ответ:</strong> Policy фиксирует required configs/tests, blocking severity, suppression owner/expiry и platform matrix. Необнаруженный defect не считается доказательством отсутствия риска.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":907},{"id":"content/06_tools_build_debug/03_debugging.md:edf205ac7ffe36a8:1","question":"<p>(L1, T) Что такое post-mortem debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Post-mortem — исследование сохранённого state после завершения/crash process. В отличие от live run нельзя продолжить execution и воспроизвести прошлые события.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":919},{"id":"content/06_tools_build_debug/03_debugging.md:3f1fef08f55239ae:1","question":"<p>(L1, T) Зачем нужен core dump после crash?</p>\n","answer":"<p><strong>Ответ:</strong> Core сохраняет registers, thread stacks и часть memory в момент сбоя. Это позволяет проверить context без немедленного воспроизведения.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":925},{"id":"content/06_tools_build_debug/03_debugging.md:7bc7a39dbbf7fbf4:1","question":"<p>(L1, P) Как открыть core dump в GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gdb ./app core</code>, затем <code>bt full</code> и <code>thread apply all bt</code>. Нужны соответствующие binary и loaded libraries.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":931},{"id":"content/06_tools_build_debug/03_debugging.md:07987f8c675a08cf:1","question":"<p>(L1, T) Почему stripped binary затрудняет анализ?</p>\n","answer":"<p><strong>Ответ:</strong> Удалённая debug information лишает source/types/locals. Matching separate symbols могут восстановить доступную diagnosis без замены runtime binary.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":937},{"id":"content/06_tools_build_debug/03_debugging.md:f077d54b6cb32994:1","question":"<p>(L1, T) Что значит “бинарь соотносится с core dump”?</p>\n","answer":"<p><strong>Ответ:</strong> Это exact executable build и compatible saved mappings/modules. Проверяют build-id и artifact provenance, а не только filename.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L1","line":943},{"id":"content/06_tools_build_debug/03_debugging.md:9741af3c1bde88fa:1","question":"<p>(L2, D) Как понять причину падения по core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Определяют signal/faulting thread, PC/instruction/operands, stacks и object invariants. Core показывает state detection, который может быть следствием более ранней ошибки.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":951},{"id":"content/06_tools_build_debug/03_debugging.md:5ebd9a96b1ecee3a:1","question":"<p>(L2, P) Как получить backtrace всех потоков из core dump?</p>\n","answer":"<p><strong>Ответ:</strong> В GDB: <code>thread apply all bt full</code>. Вывод защищают: locals могут содержать credentials и пользовательские данные.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":957},{"id":"content/06_tools_build_debug/03_debugging.md:5bdd41f0ca2c1798:1","question":"<p>(L2, D) Как понять, какой поток упал первым?</p>\n","answer":"<p><strong>Ответ:</strong> Обычно core notes/debugger указывают thread, получивший fatal signal. Это не обязательно thread, который раньше повредил память.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":963},{"id":"content/06_tools_build_debug/03_debugging.md:7d281c13df64ba26:1","question":"<p>(L2, D) Что делать, если бинарь stripped, но debug package есть?</p>\n","answer":"<p><strong>Ответ:</strong> Загружают matching separate debug files через build-id/debuglink/search paths. Debug package другой version может дать ложные source locations.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":969},{"id":"content/06_tools_build_debug/03_debugging.md:535bab61f6f0782a:1","question":"<p>(L2, D) Почему адреса в core dump не совпадают с исходниками?</p>\n","answer":"<p><strong>Ответ:</strong> Причины: ASLR/load bias, другой build, wrong source revision и optimization. Сначала подтверждают exact artifact mapping.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":975},{"id":"content/06_tools_build_debug/03_debugging.md:98cdeca765ddaec1:1","question":"<p>(L2, T) Как ASLR влияет на post-mortem анализ?</p>\n","answer":"<p><strong>Ответ:</strong> ASLR меняет load addresses, поэтому raw PC нормализуют по mappings/load bias. Для symbolication нужна точная module identity.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":981},{"id":"content/06_tools_build_debug/03_debugging.md:d06b331527e146cf:1","question":"<p>(L2, P) Как использовать <code>info sharedlibrary</code> в GDB?</p>\n","answer":"<p><strong>Ответ:</strong> <code>info sharedlibrary</code> показывает известные GDB shared objects и symbol status. При offline analysis настраивают sysroot/search paths к сохранённым dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":987},{"id":"content/06_tools_build_debug/03_debugging.md:2392aa2d5c0b9a3a:1","question":"<p>(L2, D) Как понять, какая версия библиотеки была загружена во время crash?</p>\n","answer":"<p><strong>Ответ:</strong> Сверяют module paths, build-ids и immutable release inventory. Одного SONAME недостаточно для точной версии реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":993},{"id":"content/06_tools_build_debug/03_debugging.md:94a193ba3d4dcbbc:1","question":"<p>(L2, D) Как расследовать crash в фоне, когда нет возможности воспроизвести локально?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют core, artifacts, config revision и безопасные logs, формулируют hypotheses и проверяют invariants. Для следующего occurrence добавляют targeted telemetry.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":999},{"id":"content/06_tools_build_debug/03_debugging.md:ee0d449e3a58b924:1","question":"<p>(L2, T) Чем post-mortem отличается от live-debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Core неизменяем и ограничен сохранёнными данными; live debugging позволяет stepping/watchpoints, но меняет timing и process state.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":1005},{"id":"content/06_tools_build_debug/03_debugging.md:d26b96b04750a19e:1","question":"<p>(L3, D) Как анализировать production crash без исходников всех зависимостей?</p>\n","answer":"<p><strong>Ответ:</strong> Используют exported symbols, debug packages, disassembly, ABI и caller contracts. Неизвестные source/locals явно ограничивают уверенность analysis.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1013},{"id":"content/06_tools_build_debug/03_debugging.md:2a08fa39d81c773a:1","question":"<p>(L3, D) Как расследовать crash внутри allocator'а?</p>\n","answer":"<p><strong>Ответ:</strong> Ищут invalid free, overwritten metadata, UAF и races раньше обнаружения. Sanitizer reproduction часто показывает offending access ближе к root cause.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":1019},{"id":"content/06_tools_build_debug/03_debugging.md:2f2c7e32b46cb32d:1","question":"<p>(L3, D) Как понять, что первичная ошибка произошла задолго до падения?</p>\n","answer":"<p><strong>Ответ:</strong> Несогласованные object/allocator invariants и поздний consumer crash дают гипотезу. Её подтверждают lifetime history, earlier logs или instrumented reproduction.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1025},{"id":"content/06_tools_build_debug/03_debugging.md:03da0570abcc734d:1","question":"<p>(L3, T) Что такое split debug info и build-id?</p>\n","answer":"<p><strong>Ответ:</strong> Split debug info отделяет descriptions от runtime code; build-id идентифицирует artifact. Он помогает lookup, но не заменяет source/config provenance.</p>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/contents.html\">System V ABI: ELF</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":1031},{"id":"content/06_tools_build_debug/03_debugging.md:7abc4554ecb04b6b:1","question":"<p>(L3, P) Как использовать build-id для поиска символов?</p>\n","answer":"<p><strong>Ответ:</strong> Читают build-id, затем ищут corresponding debug artifact в configured directory/service. Проверяют identity before load, не подбирают «похожую» version.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/\">GNU Binutils</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":1037},{"id":"content/06_tools_build_debug/03_debugging.md:d6c78a172269c8a6:1","question":"<p>(L3, D) Как расследовать crash в multithreaded сервисе по core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Изучают все threads, queues, object owners и locks, начиная с fatal context. Snapshot не показывает полную history и сам не доказывает race.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1043},{"id":"content/06_tools_build_debug/03_debugging.md:d073f1f857df6ece:1","question":"<p>(L3, D) Как отличить memory corruption от логической ошибки по core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют addresses, types и invariants: impossible pointer/layout может указывать corruption, valid state с неверным branch — logic. Окончательный вывод требует дополнительных evidence.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1049},{"id":"content/06_tools_build_debug/03_debugging.md:867b0067ae0468e9:1","question":"<p>(L3, D) Как извлекать полезный контекст: аргументы, глобальные объекты, состояние очередей?</p>\n","answer":"<p><strong>Ответ:</strong> Используют <code>info args/locals</code>, print known objects и bounded memory inspection. Для STL нужны matching pretty printers; повреждённые containers нельзя обходить без limits.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1055},{"id":"content/06_tools_build_debug/03_debugging.md:a61f11c89824a07b:1","question":"<p>(L3, D) Что делать, если core dump слишком большой или обрезанный?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют collector/size/filter policy и доступные mappings. Для следующих crashes настраивают полезный scope/limits; отсутствующие страницы восстановить из core невозможно.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1061},{"id":"content/06_tools_build_debug/03_debugging.md:497cb33e5839073a:1","question":"<p>(L3, S) Как организовать автоматический сбор и разбор core dump'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Collector сохраняет core и metadata, worker symbolicates по exact build-id, группирует signature и открывает triage record. Access/retention учитывают sensitive memory.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L3","line":1067},{"id":"content/06_tools_build_debug/03_debugging.md:87cd9c684dfd4915:1","question":"<p>(L4, S) Как строить production crash triage pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Pipeline связывает release, crash metadata, symbols, bounded automated analysis, deduplication и owner. Отдельно отслеживают collection/symbolication failures.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1075},{"id":"content/06_tools_build_debug/03_debugging.md:ef48cf9444385c48:1","question":"<p>(L4, D) Как кластеризовать одинаковые crash'и по stack trace / signature?</p>\n","answer":"<p><strong>Ответ:</strong> Нормализуют PC по module/build-id и сравнивают stable frames/error type. Одна signature может объединять разные corruption causes; grouping проверяют.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1081},{"id":"content/06_tools_build_debug/03_debugging.md:ff2f38d2feebc3f3:1","question":"<p>(L4, S) Как обеспечить соответствие: бинарь, symbols, config, core?</p>\n","answer":"<p><strong>Ответ:</strong> Artifacts immutable, подписаны/хешированы и связаны release manifest. Core record содержит build-id, dependency/config revisions и timestamp.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1087},{"id":"content/06_tools_build_debug/03_debugging.md:453f859718094ef9:1","question":"<p>(L4, D) Как анализировать crash после hotfix, если символы потеряны?</p>\n","answer":"<p><strong>Ответ:</strong> Ищут exact CI/package artifacts и matching source. Rebuild может отличаться; без подтверждения identity symbolication считают приблизительной.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1093},{"id":"content/06_tools_build_debug/03_debugging.md:a13abfd3f2676a75:1","question":"<p>(L4, S) Как сделать post-mortem анализ стандартной инженерной практикой в команде?</p>\n","answer":"<p><strong>Ответ:</strong> Вводят artifact retention, runbooks, ownership, regular drills и review corrective actions. Проверяют не только crash fix, но и пригодность collected evidence.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1099},{"id":"content/06_tools_build_debug/03_debugging.md:2c410c5d19311872:1","question":"<p>(L1, T) Зачем нужен logging?</p>\n","answer":"<p><strong>Ответ:</strong> Logging фиксирует события и diagnostic context для operations, audit и debugging. Он дополняет metrics/traces, а не заменяет их.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1111},{"id":"content/06_tools_build_debug/03_debugging.md:7482b82aa5b57635:1","question":"<p>(L1, T) Какие бывают уровни логирования?</p>\n","answer":"<p><strong>Ответ:</strong> Часто используют TRACE, DEBUG, INFO, WARN, ERROR, FATAL; semantics задаёт проект/library. Единое соглашение важнее названий.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1117},{"id":"content/06_tools_build_debug/03_debugging.md:5578cc21c6b69141:1","question":"<p>(L1, T) Чем <code>INFO</code> отличается от <code>DEBUG</code>?</p>\n","answer":"<p><strong>Ответ:</strong> INFO отражает normal operational events, DEBUG — подробности diagnosis. Production verbosity выбирают по ценности, overhead и confidentiality.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1123},{"id":"content/06_tools_build_debug/03_debugging.md:86c964cdb4a107eb:1","question":"<p>(L1, T) Когда использовать <code>ERROR</code> и <code>FATAL</code>?</p>\n","answer":"<p><strong>Ответ:</strong> ERROR — failed operation, требующая внимания; FATAL — событие с termination по policy. Не каждую recoverable retry ошибку нужно считать fatal.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1129},{"id":"content/06_tools_build_debug/03_debugging.md:3be36bc136e9a87e:1","question":"<p>(L1, P) Какие поля полезно включать в лог?</p>\n","answer":"<p><strong>Ответ:</strong> Timestamp, severity, service/version, event name, request/connection ID и safe context. Secrets и raw personal payload исключают.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1135},{"id":"content/06_tools_build_debug/03_debugging.md:d9901be5c06f85f8:1","question":"<p>(L1, T) Что такое structured logging?</p>\n","answer":"<p><strong>Ответ:</strong> Structured logging хранит отдельные типизированные fields вместо неформального текста. Это облегчает фильтрацию и aggregation.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1141},{"id":"content/06_tools_build_debug/03_debugging.md:34d615a9f389d06c:1","question":"<p>(L1, T) Почему plain text логов может быть недостаточно?</p>\n","answer":"<p><strong>Ответ:</strong> Нестабильные сообщения трудно парсить, связывать и сравнивать. Schema даёт однозначные event names, IDs и error categories.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1147},{"id":"content/06_tools_build_debug/03_debugging.md:f11db1181240a006:1","question":"<p>(L1, P) Что важно логировать при ошибке?</p>\n","answer":"<p><strong>Ответ:</strong> Логируют operation/stage, native error, safe endpoint/context и correlation ID. errno сохраняют сразу после failed syscall.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>; <a href=\"https://man7.org/linux/man-pages/man7/socket.7.html\">socket(7)</a>.</p>\n","group":"L1","line":1153},{"id":"content/06_tools_build_debug/03_debugging.md:325b3c391d2840c0:1","question":"<p>(L1, D) Почему “слишком мало логов” мешает расследованию?</p>\n","answer":"<p><strong>Ответ:</strong> Не хватает stage/state, чтобы связать symptom с механизмом. Требования к diagnostic fields проектируют до incident.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1159},{"id":"content/06_tools_build_debug/03_debugging.md:0f1889d122255a8d:1","question":"<p>(L1, D) Почему “слишком много логов” тоже проблема?</p>\n","answer":"<p><strong>Ответ:</strong> Logs потребляют CPU/I/O/storage, создают noise и могут раскрыть secrets. Нужны levels, sampling и bounded queues.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L1","line":1165},{"id":"content/06_tools_build_debug/03_debugging.md:45288470278fc187:1","question":"<p>(L2, T) Что такое correlation ID / request ID?</p>\n","answer":"<p><strong>Ответ:</strong> ID связывает события одной operation через threads/services. Для retries полезны общий request ID и отдельный attempt ID.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1173},{"id":"content/06_tools_build_debug/03_debugging.md:21a529756df3bc1b:1","question":"<p>(L2, T) Как логирование помогает в distributed/system-level debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Общие IDs и stage events позволяют построить path/timeline между компонентами. Clock skew и missing events учитывают явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1179},{"id":"content/06_tools_build_debug/03_debugging.md:e42f6ab5ed2ef187:1","question":"<p>(L2, D) Как понять по логам порядок событий в многопоточном приложении?</p>\n","answer":"<p><strong>Ответ:</strong> Используют thread/task IDs, sequence numbers и explicit synchronization events. Timestamp order не всегда доказывает causal/happens-before order.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1185},{"id":"content/06_tools_build_debug/03_debugging.md:bbfbed648ffa34b9:1","question":"<p>(L2, T) Что такое synchronous vs asynchronous logging?</p>\n","answer":"<p><strong>Ответ:</strong> Sync logging выполняет output на request path; async помещает records в queue. Async тоже требует bounded memory и overflow policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1191},{"id":"content/06_tools_build_debug/03_debugging.md:aa12a4eee5b4c684:1","question":"<p>(L2, T) Как логи влияют на latency?</p>\n","answer":"<p><strong>Ответ:</strong> Formatting, locks, allocation и output добавляют delay; async queue может block или drop. Измеряют tail latency под реальной verbosity.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1197},{"id":"content/06_tools_build_debug/03_debugging.md:441efab2627dcdd0:1","question":"<p>(L2, D) Почему verbose logging может скрыть race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Logging меняет scheduling и может добавлять synchronization. Исчезновение race при verbose mode — clue, а не исправление.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L2","line":1203},{"id":"content/06_tools_build_debug/03_debugging.md:9eb3f1643879246b:1","question":"<p>(L2, P) Как выбирать log level для production?</p>\n","answer":"<p><strong>Ответ:</strong> Оставляют actionable operational/error events, подробности включают targeted и временно. У каждой категории должны быть cost/privacy ограничения.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1209},{"id":"content/06_tools_build_debug/03_debugging.md:624e54bc4e9f2b13:1","question":"<p>(L2, T) Как логировать исключения и errno-коды?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют error code/type, operation и safe message. errno читают до других calls; exception messages проверяют на sensitive content.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1215},{"id":"content/06_tools_build_debug/03_debugging.md:0662ad130488bb95:1","question":"<p>(L2, P) Какие события обязательно логировать в daemon/service?</p>\n","answer":"<p><strong>Ответ:</strong> Полезны startup/config version, readiness, shutdown/reload, dependency failures и resource exhaustion. Per-request logs выбирают по load и debugging needs.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1221},{"id":"content/06_tools_build_debug/03_debugging.md:5a48ad5908721376:1","question":"<p>(L2, D) Как коррелировать логи с stack trace и crash timestamp?</p>\n","answer":"<p><strong>Ответ:</strong> Связывают instance/build-id, request ID, signal и crash time с clock context. PID без start time/release identity недостаточен.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L2","line":1227},{"id":"content/06_tools_build_debug/03_debugging.md:e68323e40de7a83e:1","question":"<p>(L3, T) Как structured logging упрощает автоматический анализ?</p>\n","answer":"<p><strong>Ответ:</strong> Fields позволяют queries и grouping без regex по prose. Stable schema также облегчает automated incident correlation.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1235},{"id":"content/06_tools_build_debug/03_debugging.md:124c4cec0c84df50:1","question":"<p>(L3, T) Как формировать schema логов?</p>\n","answer":"<p><strong>Ответ:</strong> Определяют event names, required IDs/types, optional context, schema version и redaction. Cardinality/retention планируют заранее.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1241},{"id":"content/06_tools_build_debug/03_debugging.md:face567bab72b3c6:1","question":"<p>(L3, D) Почему логирование может менять timing и маскировать баг?</p>\n","answer":"<p><strong>Ответ:</strong> Formatting/I/O/locks меняют timing и allocation. Поэтому измеряют logger overhead и применяют sampling/narrow tracing для timing-sensitive issues.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1247},{"id":"content/06_tools_build_debug/03_debugging.md:fa4a096cd13c097e:1","question":"<p>(L3, D) Как расследовать инцидент, если есть только логи и нет core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Строят timeline и проверяемые hypotheses по state transitions, признавая missing memory/history. Добавляют targeted evidence для следующего occurrence.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1253},{"id":"content/06_tools_build_debug/03_debugging.md:9053f389b7d92fe8:1","question":"<p>(L3, S) Как балансировать observability и overhead?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют high-value events, используют sampling/aggregation и ограниченные queues. Проверяют overhead и diagnostic coverage на representative incident scenarios.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1259},{"id":"content/06_tools_build_debug/03_debugging.md:40250ae50168ca22:1","question":"<p>(L3, T) Как логировать безопасно с точки зрения sensitive data?</p>\n","answer":"<p><strong>Ответ:</strong> Применяют allowlist fields, redaction, access controls и retention. Не логируют keys, passwords, bearer tokens и необработанный sensitive payload.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1265},{"id":"content/06_tools_build_debug/03_debugging.md:a71f8ebc0179008a:1","question":"<p>(L3, D) Почему логи из нескольких потоков трудно интерпретировать?</p>\n","answer":"<p><strong>Ответ:</strong> Physical write order зависит от buffering/scheduling и не обязательно отражает event causality. Thread/task IDs и sequence numbers уменьшают ambiguity.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1271},{"id":"content/06_tools_build_debug/03_debugging.md:cb05936ac793d931:1","question":"<p>(L3, P) Какие метаданные полезны для production crash investigation?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны build-id/revision, instance/start time, config/dependency versions, signal/PC и correlation IDs. Environment сохраняют без secrets.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1277},{"id":"content/06_tools_build_debug/03_debugging.md:551e37c0add0918f:1","question":"<p>(L3, T) Как sampling логов влияет на debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Sampling снижает cost, но может потерять редкий causal event. Errors/state transitions и correlated trace sampling требуют отдельной policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1283},{"id":"content/06_tools_build_debug/03_debugging.md:00b6ffe4e86542c1:1","question":"<p>(L3, S) Как стандартизировать logging policy в команде?</p>\n","answer":"<p><strong>Ответ:</strong> Policy задаёт schema, levels, PII/secrets rules, retention, ownership и overflow behavior. Library wrapper помогает обеспечить defaults единообразно.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L3","line":1289},{"id":"content/06_tools_build_debug/03_debugging.md:634040b73e85f23f:1","question":"<p>(L4, S) Как строить logging strategy для high-load C++ сервиса?</p>\n","answer":"<p><strong>Ответ:</strong> Используют bounded async pipeline, efficient formatting, per-category sampling и monitoring drops/backlog. Critical diagnostic events должны иметь отдельную loss policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L4","line":1297},{"id":"content/06_tools_build_debug/03_debugging.md:4e24dd131d662d75:1","question":"<p>(L4, S) Когда логирование нужно дополнять metrics/tracing, а не расширять?</p>\n","answer":"<p><strong>Ответ:</strong> Metrics подходят для trends/rates, tracing — для request path/latency; logs — для discrete context. Увеличение verbosity не заменяет missing phase timings.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L4","line":1303},{"id":"content/06_tools_build_debug/03_debugging.md:baeb56f0e09ec03b:1","question":"<p>(L4, D) Как расследовать rare production bug при минимальном допустимом логировании?</p>\n","answer":"<p><strong>Ответ:</strong> Добавляют narrow event records, ring buffer/flight recorder, targeted sampling и safe state snapshots. Проверяют privacy и измеряют влияние на timing.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L4","line":1309},{"id":"content/06_tools_build_debug/03_debugging.md:13d8ae783fc2583f:1","question":"<p>(L4, S) Как проектировать логирование так, чтобы оно помогало post-mortem анализу?</p>\n","answer":"<p><strong>Ответ:</strong> Включают build/instance IDs, stage transitions и link к artifacts; crash collector связывает logs/core. Последние buffered records могут не пережить fatal signal.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L4","line":1315},{"id":"content/06_tools_build_debug/03_debugging.md:82295bb2a46c4b7a:1","question":"<p>(L4, S) Как формализовать требования к диагностической информации в production?</p>\n","answer":"<p><strong>Ответ:</strong> Для failure classes фиксируют required evidence, overhead budget, retention/access и acceptance drills. Требования проверяют моделированием incidents.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L4","line":1321},{"id":"content/06_tools_build_debug/03_debugging.md:166ac1918b81f96d:1","question":"<p>(L2, D) Программа падает с <code>SIGSEGV</code>: какие первые 5 шагов расследования?</p>\n","answer":"<p><strong>Ответ:</strong> Фиксируют release/scope, сохраняют core/logs, проверяют exact artifacts, изучают fatal thread/PC и все stacks. Затем строят hypotheses и regression reproduction.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":1333},{"id":"content/06_tools_build_debug/03_debugging.md:fc2a556522bec83c:1","question":"<p>(L2, D) Есть core dump, но нет символов: что делать?</p>\n","answer":"<p><strong>Ответ:</strong> Ищут matching debug packages/build-id archive. Если их нет, используют symbols/disassembly/maps, отмечая ограничения; чужая сборка может ввести в заблуждение.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>.</p>\n","group":"L2","line":1339},{"id":"content/06_tools_build_debug/03_debugging.md:cf0a5b5fcf0a7ac7:1","question":"<p>(L2, D) Программа зависла, а не упала: как дебажить?</p>\n","answer":"<p><strong>Ответ:</strong> Снимают repeated all-thread stacks и syscall/CPU state. Различают deadlock, blocked I/O, busy loop и starvation.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man1/strace.1.html\">strace(1)</a>; <a href=\"https://man7.org/linux/man-pages/man1/perf-stat.1.html\">perf-stat(1)</a>.</p>\n","group":"L2","line":1345},{"id":"content/06_tools_build_debug/03_debugging.md:35f333f844480b34:1","question":"<p>(L2, D) Утечка памяти растет медленно неделями: какой план анализа?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнивают live heap/allocation profiles во времени при известном workload. Отделяют leaks от pools/fragmentation/RSS и сужают растущие allocation stacks.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L2","line":1351},{"id":"content/06_tools_build_debug/03_debugging.md:284c4e9e2e678ac9:1","question":"<p>(L2, D) После включения <code>-O2</code> баг появился, а под GDB исчезает: почему так бывает?</p>\n","answer":"<p><strong>Ответ:</strong> Optimization проявляет UB/races, debugger меняет layout/timing. Сохраняют exact optimized build, применяют sanitizers и минимизируют scenario.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimization Options</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>.</p>\n","group":"L2","line":1357},{"id":"content/06_tools_build_debug/03_debugging.md:b8382456caf56889:1","question":"<p>(L3, D) Падение происходит только под нагрузкой и только ночью: как строить расследование?</p>\n","answer":"<p><strong>Ответ:</strong> Коррелируют workload, scheduled jobs, resource pressure и config/deploys; сохраняют artifacts/core и временные metrics. Ночное совпадение само по себе не причина.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://sre.google/sre-book/effective-troubleshooting/\">Google SRE: Effective Troubleshooting</a>.</p>\n","group":"L3","line":1365},{"id":"content/06_tools_build_debug/03_debugging.md:fe72289503998606:1","question":"<p>(L3, D) Crash внутри <code>std::string</code>/<code>malloc</code>: как понять, что корень проблемы раньше?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяют caller ownership, bounds и object lifetime; library могла лишь первой прочитать повреждённое состояние. ASan ищет ранний write/free.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":1371},{"id":"content/06_tools_build_debug/03_debugging.md:10c33bb149f0ce3e:1","question":"<p>(L3, D) Есть только логи и адрес падения из syslog: как двигаться дальше?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют release/build-id, fault PC, module mappings и time; нормализуют address для symbolication. Без load bias или exact artifacts вывод ограничен.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/\">GNU Binutils</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L3","line":1377},{"id":"content/06_tools_build_debug/03_debugging.md:50d7b2163962ea29:1","question":"<p>(L3, D) Один поток “висит”, остальные ждут: как искать deadlock?</p>\n","answer":"<p><strong>Ответ:</strong> Снимают stacks всех threads, определяют held/waited locks и строят wait-for cycle. Проверяют thread, выполняющий I/O/CPU, а не только mutex waits.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>; <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>.</p>\n","group":"L3","line":1383},{"id":"content/06_tools_build_debug/03_debugging.md:6897d29ebb752118:1","question":"<p>(L3, D) Sanitizer находит баг, но стек указывает в allocator/runtime: как локализовать исходный код?</p>\n","answer":"<p><strong>Ответ:</strong> Читают allocation/free/access stacks первого report, caller input и object lifetime. При missing symbols загружают exact debug artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://valgrind.org/docs/manual/mc-manual.html\">Valgrind: Memcheck</a>.</p>\n","group":"L3","line":1389},{"id":"content/06_tools_build_debug/03_debugging.md:cd646df0438fe16b:1","question":"<p>(L4, S) Как построить единую стратегию debugging для legacy C/C++ продукта?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны reliable artifacts/symbols, crash collection, structured events и staged sanitizer coverage. Начинают с критичных paths и measurable diagnostic gaps.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>; <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>; <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>.</p>\n","group":"L4","line":1397},{"id":"content/06_tools_build_debug/03_debugging.md:fe06bed2553af4b0:1","question":"<p>(L4, S) Как сократить MTTR для production crash'ей в 2–3 раза?</p>\n","answer":"<p><strong>Ответ:</strong> Автоматизируют collection/matching/symbolication, triage ownership и runbooks, измеряют текущий MTTR. Конкретное ускорение проверяют на incidents, не обещают заранее.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/managing-incidents/\">Google SRE: Managing Incidents</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB Manual</a>.</p>\n","group":"L4","line":1403},{"id":"content/06_tools_build_debug/03_debugging.md:04a2d798ff4fccdd:1","question":"<p>(L4, S) Какие артефакты должны автоматически сохраняться при падении сервиса?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняют core или registers/maps, build/dependency/config identities и safe logs/time. Secrets в memory требуют restricted access и retention.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">core(5)</a>; <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>.</p>\n","group":"L4","line":1409},{"id":"content/06_tools_build_debug/03_debugging.md:1f69c0cf5a539a3e:1","question":"<p>(L4, S) Как стандартизировать требования к symbol retention, logging и sanitizer builds?</p>\n","answer":"<p><strong>Ответ:</strong> Policy связывает retention с release support, задаёт logging schema/privacy и required sanitizer jobs. Recovery drills проверяют пригодность exact artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html\">OWASP: Logging</a>; <a href=\"https://reproducible-builds.org/docs/\">Reproducible Builds Documentation</a>.</p>\n","group":"L4","line":1415},{"id":"content/06_tools_build_debug/03_debugging.md:f1b9057393bd4d0d:1","question":"<p>(L4, S) Как внедрить культуру доказательного расследования инцидентов, а не “угадывания по логу”?</p>\n","answer":"<p><strong>Ответ:</strong> Разделяют факты/гипотезы, требуют предсказаний tests и causal evidence, ведут timeline и review corrective actions. Ошибочные гипотезы фиксируют без поиска виноватых.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/effective-troubleshooting/\">Google SRE: Effective Troubleshooting</a>; <a href=\"https://sre.google/sre-book/managing-incidents/\">Google SRE: Managing Incidents</a>.</p>\n","group":"L4","line":1421}];
